"use client";

import { useEffect, useState } from "react";
import { User, UserRole } from "@/lib/auth";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  User as UserIcon,
  Shield,
  Upload,
  X,
  Loader2,
} from "lucide-react";
import { toast } from "sonner";

import { SYSTEM_ORG_ID } from "@/lib/constants";
import { PERMISSION_LABELS } from "@/lib/permissions";

type Props = {
  onOpenChange: (open: boolean) => void;
  onSave: (data: FormData) => void;
  initialData?: Partial<User>;
  isNew?: boolean;
  isLoading?: boolean;
};

export function UserForm({
  onOpenChange,
  onSave,
  initialData,
  isNew = true,
  isLoading = false,
}: Props) {
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [role, setRole] = useState<UserRole>(UserRole.CUSTOMER);
  const [profileImage, setProfileImage] = useState<File | null>(null);
  const [permissions, setPermissions] = useState<string>("");
  const [preview, setPreview] = useState<string | null>(null);

  useEffect(() => {
    if (!initialData) return;
    setFullName(initialData.fullName || "");
    setEmail(initialData.email || "");
    setPhoneNumber(initialData.phoneNumber || "");
    setRole((initialData.role as UserRole) || UserRole.CUSTOMER);
    if (
      initialData.profileImage &&
      typeof initialData.profileImage === "string"
    ) {
      setPreview(initialData.profileImage);
    }
    // Handle permissions if backend returns it as array
    if (initialData.permissions && Array.isArray(initialData.permissions)) {
      setPermissions(initialData.permissions.join(", "));
    }
  }, [initialData]);

  useEffect(() => {
    if (!profileImage) return;
    const url = URL.createObjectURL(profileImage);
    setPreview(url);
    return () => URL.revokeObjectURL(url);
  }, [profileImage]);

  const handleSubmit = () => {
    // Validation
    if (!fullName.trim()) return toast.error("Please enter full name");
    if (role === UserRole.CUSTOMER && !email.trim() && !phoneNumber.trim()) {
      return toast.error("Please enter email or phone number");
    }
    if (role !== UserRole.CUSTOMER && !email.trim()) {
      return toast.error("Email is required for staff accounts");
    }
    if (role !== UserRole.CUSTOMER && !phoneNumber.trim()) {
      return toast.error("Phone number is required for staff accounts");
    }
    if (!role) return toast.error("Please select a user role");

    const formData = new FormData();
    formData.append("fullName", fullName);
    formData.append("email", email);
    formData.append("phoneNumber", phoneNumber);
    formData.append("role", role);
    formData.append("isStaffUser", "true");

    // Default orgId for system users
    if (role === UserRole.SYSTEM_SUPER_ADMIN || role === UserRole.SYSTEM_ADMIN) {
      formData.append("orgId", SYSTEM_ORG_ID);
    }

    if (profileImage) {
      formData.append("profileImage", profileImage);
    }

    // Add Permissions
    if (permissions) {
      // Split by comma, trim whitespace, remove duplicates/empty strings
      const perms = permissions.split(",")
        .map(p => p.trim())
        .filter(p => p !== "");

      perms.forEach(p => formData.append("permissions", p));
    }

    onSave(formData);
  };

  return (
    <div className="w-full h-full flex flex-col bg-white overflow-hidden">
      {/* Top Header */}
      <div className="flex items-center justify-between px-4 md:px-8 py-5 shrink-0 bg-white border-b shadow-sm z-20">
        <h2 className="text-xl font-bold text-slate-900">
          {isNew ? "Add System User" : "Update User Account"}
        </h2>
        <Button
          variant="ghost"
          onClick={() => onOpenChange(false)}
          className="h-10 w-10 p-0 rounded-full hover:bg-slate-100 flex items-center justify-center border shadow-sm"
        >
          <X className="h-5 w-5 text-slate-500" />
        </Button>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto px-4 md:px-10 pb-6 bg-slate-50/30">
        <div className="max-w-6xl mx-auto h-full pt-10">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            {/* Account Roles & Profile Box */}
            <div className="lg:col-span-12">
              <div className="bg-white p-10 rounded-3xl border border-slate-200 shadow-sm space-y-10">
                <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">
                  <span className="p-3 bg-primary/5 rounded-2xl text-primary">
                    <Shield className="h-6 w-6" />
                  </span>
                  User Details
                </h3>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                  {/* Left Column: Profile Photo */}
                  <div className="lg:col-span-4">
                    <div className="flex flex-col items-center justify-center gap-6 p-8 border-2 border-dashed border-slate-100 rounded-3xl bg-slate-50/50 h-full">
                      <div className="h-44 w-44 rounded-full border-8 border-white shadow-2xl flex items-center justify-center bg-slate-200 overflow-hidden relative group cursor-pointer transition-transform hover:scale-105">
                        {preview ? (
                          <img
                            src={preview}
                            alt="Preview"
                            className="h-full w-full object-cover"
                          />
                        ) : (
                          <UserIcon className="h-16 w-16 text-slate-400" />
                        )}
                        <label
                          htmlFor="profileImage"
                          className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer"
                        >
                          <Upload className="h-10 w-10 text-white" />
                        </label>
                      </div>

                      <div className="text-center">
                        <Label
                          htmlFor="profileImage"
                          className="cursor-pointer text-sm font-black text-primary hover:opacity-80 transition-all flex items-center gap-2 px-6 py-2 rounded-full border border-primary/20 bg-white shadow-sm"
                        >
                          <Upload className="h-4 w-4" /> Add Photo
                        </Label>
                        <input
                          id="profileImage"
                          type="file"
                          accept="image/*"
                          className="hidden"
                          onChange={(e) =>
                            setProfileImage(e.target.files?.[0] || null)
                          }
                        />
                      </div>
                    </div>
                  </div>

                  {/* Right Column: Form Fields */}
                  <div className="lg:col-span-8 space-y-6">
                    <div className="space-y-3">
                      <Label className="text-sm font-black text-slate-900">
                        Full Name *
                      </Label>
                      <Input
                        className="h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold px-4 focus:ring-2 focus:ring-primary/20"
                        placeholder="e.g. Samuel Ayele"
                        value={fullName}
                        onChange={(e) => setFullName(e.target.value)}
                      />
                    </div>

                    <div className="space-y-3">
                      <Label className="text-sm font-black text-slate-900">
                        System Permissions (Role)
                      </Label>
                      <Select
                        value={role}
                        onValueChange={(val) => setRole(val as UserRole)}
                      >
                        <SelectTrigger className="h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold">
                          <SelectValue placeholder="Choose Role" />
                        </SelectTrigger>
                        <SelectContent className="rounded-2xl shadow-2xl border-slate-100">
                          <SelectItem
                            value={UserRole.SYSTEM_SUPER_ADMIN}
                            className="h-12 font-bold text-primary"
                          >
                            System Super Admin
                          </SelectItem>
                          <SelectItem
                            value={UserRole.SYSTEM_ADMIN}
                            className="h-12 font-bold"
                          >
                            System Admin
                          </SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="space-y-3">
                      <Label className="text-sm font-black text-slate-900">
                        Assigned Organization
                      </Label>
                      <Input
                        className="h-14 w-full rounded-2xl border-slate-200 bg-slate-50 text-lg font-bold px-4 cursor-not-allowed text-slate-500"
                        value="PossibleTech"
                        readOnly
                      />
                    </div>

                    <div className="space-y-3">
                      <Label className="text-sm font-black text-slate-900">
                        Phone Number
                      </Label>
                      <Input
                        className="h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold px-4 focus:ring-2 focus:ring-primary/20"
                        placeholder="+251 9..."
                        value={phoneNumber}
                        onChange={(e) => setPhoneNumber(e.target.value)}
                      />
                    </div>

                    <div className="space-y-3">
                      <Label className="text-sm font-black text-slate-900">
                        Email Address *
                      </Label>
                      <Input
                        className="h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold px-4 focus:ring-2 focus:ring-primary/20"
                        type="email"
                        placeholder="samuel@parking-mgmt.com"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                      />
                      <div className="space-y-4 pt-4 border-t border-slate-100">
                        <Label className="text-sm font-black text-slate-900 block mb-3">
                          Access Permissions
                        </Label>
                        <div className="grid grid-cols-1 gap-3 p-4 bg-slate-50/50 rounded-2xl border border-dashed border-slate-200 h-64 overflow-y-auto">
                          {Object.entries(PERMISSION_LABELS).map(([key, label]) => {
                            // Correctly parsing string state back to array for check
                            const currentPerms = permissions
                              ? permissions.split(",").map(p => p.trim())
                              : [];
                            const isChecked = currentPerms.includes(key);

                            const handleCheck = (checked: boolean) => {
                              let newPerms = [...currentPerms];
                              if (checked) {
                                if (!newPerms.includes(key)) newPerms.push(key);
                              } else {
                                newPerms = newPerms.filter(p => p !== key);
                              }
                              setPermissions(newPerms.join(", "));
                            };

                            return (
                              <div key={key} className="flex items-center space-x-3 p-2 hover:bg-white rounded-lg transition-colors">
                                <input
                                  type="checkbox"
                                  id={key}
                                  className="h-5 w-5 rounded border-slate-300 text-primary focus:ring-primary/20"
                                  checked={isChecked}
                                  onChange={(e) => handleCheck(e.target.checked)}
                                />
                                <label
                                  htmlFor={key}
                                  className="text-sm font-bold text-slate-700 cursor-pointer select-none"
                                >
                                  {label}
                                </label>
                              </div>
                            );
                          })}
                        </div>
                        <p className="text-xs text-slate-400 font-medium px-2">
                          * "System Super Admin" has full access by default.
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Footer Navigation */}
      <div className="border-t py-6 px-4 md:px-10 bg-white shrink-0">
        <div className="max-w-6xl mx-auto flex items-center justify-end gap-4">
          <Button
            variant="ghost"
            onClick={() => onOpenChange(false)}
            className="h-14 px-8 rounded-xl font-bold text-slate-400 hover:text-slate-900"
          >
            Cancel
          </Button>

          <Button
            onClick={handleSubmit}
            disabled={isLoading}
            className="h-14 px-16 rounded-xl bg-primary hover:opacity-90 text-white font-bold transition-all min-w-[160px] shadow-lg shadow-primary/10"
          >
            {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {isNew ? "Create User" : "Update User"}
          </Button>
        </div>
      </div>
    </div>
  );
}
